import { describe, it } from 'vitest'
import { testerRun } from '../../utils/tester.utils.ts'
import { commentsCode } from './comments-code.ts'

describe('arch/comments-code', () => {
  it.each([
    { name: 'code without comments passes', code: 'const value = 1' },
    { name: 'disable directives stay', code: '// oxlint-disable-next-line no-explicit-any\nconst value: any = 1' },
    { name: 'TypeScript directives stay', code: '// @ts-expect-error upstream types are wrong\nconst value = 1' },
    { name: 'triple-slash references stay', code: '/// <reference types="node" />\nconst value = 1' },
    { name: 'pure annotations stay', code: 'const value = /*#__PURE__*/ factory()' },
    { name: 'JSX pragmas stay', code: '/** @jsxImportSource preact */\nconst value = 1' },
    { name: 'bundler hints stay', code: 'import(/* @vite-ignore */ path)' },
    { name: 'source map comments stay', code: '//# sourceMappingURL=value.js.map' },
    { name: 'legal blocks stay', code: '/*! Copyright 2026 */\nconst value = 1' },
    { name: 'formatter ignores stay', code: '// prettier-ignore\nconst value = 1' },
    { name: 'Why notes stay', code: '// Why: the cache is warmed by the worker.\nconst user = await load(id)' },
    { name: 'a Why block stays', code: '/**\n * Why: cache keys must stay stable.\n */\nconst value = 1' },
    { name: 'a Why note continues on the next line', code: '// Why: the library requires a stable key\n// across renders to preserve focus.\nconst value = 1' },
    { name: 'jsdoc keeps doc blocks', code: '/** Public contract. */\nexport const value = 1', options: { jsdoc: true } },
    { name: 'allow keeps matching comments', code: '// Copyright 2026\nconst value = 1', options: { allow: ['^Copyright'] } },
    {
      name: 'members only skips other comments',
      code: '// Function documentation.\nfunction render() {\n  // Local explanation.\n  return 1\n}',
      options: { members: 'only' },
    },
    {
      name: 'members only keeps member Why notes',
      code: 'interface Props {\n  // Why: upstream rejects null.\n  title: string\n}',
      options: { members: 'only' },
    },
    {
      name: 'a closing comment is not a member comment',
      code: 'interface Props { title: string\n  // Detached closing comment.\n}',
      options: { members: 'only' },
    },
    { name: 'array elements are not members', code: 'const [a] = [\n  // Not a member.\n  1,\n]', options: { members: 'only' } },
    { name: 'members only keeps an eslint directive', code: 'interface Props {\n // eslint-disable-next-line no-explicit-any\n title: any\n}', options: { members: 'only' } },
    { name: 'members only keeps an oxlint directive', code: 'interface Props {\n // oxlint-disable-next-line no-explicit-any\n title: any\n}', options: { members: 'only' } },
    { name: 'members only keeps a ts-expect-error', code: 'interface Props {\n // @ts-expect-error upstream types are wrong\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a ts-check', code: 'interface Props {\n // @ts-check\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a reference directive', code: 'interface Props {\n /// <reference types="node" />\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps an amd-module directive', code: 'interface Props {\n /// <amd-module name="props" />\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a spaced PURE note', code: 'interface Props {\n /* #__PURE__ */\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps an at-PURE note', code: 'interface Props {\n /* @__PURE__ */\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a spaced NO_SIDE_EFFECTS note', code: 'interface Props {\n /* @__NO_SIDE_EFFECTS__ */\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a tight NO_SIDE_EFFECTS note', code: 'interface Props {\n /*#__NO_SIDE_EFFECTS__*/\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a jsx pragma', code: 'interface Props {\n /** @jsx h */\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a jsxImportSource pragma', code: 'interface Props {\n /** @jsxImportSource preact */\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a jsxRuntime pragma', code: 'interface Props {\n /** @jsxRuntime automatic */\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a jsxFrag pragma', code: 'interface Props {\n /** @jsxFrag Fragment */\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a vite hint', code: 'interface Props {\n /* @vite-ignore */\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a source map comment', code: 'interface Props {\n //# sourceMappingURL=props.js.map\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a legal block', code: 'interface Props {\n /*! Copyright 2026 */\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a prettier ignore', code: 'const o = {\n // prettier-ignore\n k: 1,\n}', options: { members: 'only' } },
    { name: 'members only keeps a Why note on a spread', code: 'const o = {\n // Why: order matters here.\n ...rest,\n}', options: { members: 'only' } },
    { name: 'members only skips one-space array elements', code: 'const [a] = [\n // Array hole, not a member.\n 1,\n]', options: { members: 'only' } },
    { name: 'members only keeps an object Why note', code: 'const props = {\n // Why: upstream rejects null.\n title: "Hello"\n}', options: { members: 'only' } },
    { name: 'members only passes without comments', code: 'interface Props { title: string }', options: { members: 'only' } },
    { name: 'members only skips a doc block above a type', code: '/** Public contract. */\ninterface Props { title: string }', options: { members: 'only' } },
    { name: 'members only skips class fields', code: 'class Props {\n // Class field.\n title = "Hello"\n}', options: { members: 'only' } },
    { name: 'members only keeps a line Why note', code: 'interface Props {\n // Why: the library requires a stable key.\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a Why doc block', code: 'interface Props {\n /**\n  * Why: the library requires a stable key.\n  */\n title: string\n}', options: { members: 'only' } },
    { name: 'members only keeps a Why block', code: 'interface Props {\n /* Why: the library requires a stable key. */\n title: string\n}', options: { members: 'only' } },
    {
      name: 'members only keeps a continued Why note',
      code: 'interface Props {\n // Why: the library requires a stable key\n // across renders to preserve focus.\n title: string\n}',
      options: { members: 'only' },
    },
    { name: 'members only keeps a trailing Why note', code: 'interface Props { title: string; // Why: upstream rejects null.\n}', options: { members: 'only' } },
    { name: 'eslint directives stay', code: '// eslint-disable-next-line no-explicit-any\nconst value: any = 1' },
    { name: 'ts-ignore stays', code: '// @ts-ignore legacy\nconst value = 1' },
    { name: 'ts-nocheck stays', code: '// @ts-nocheck\nconst value = 1' },
    { name: 'ts-check stays', code: '// @ts-check\nconst value = 1' },
    { name: 'amd-module directives stay', code: '/// <amd-module name="value" />\nconst value = 1' },
    { name: 'at-PURE annotations stay', code: 'const value = /* @__PURE__ */ factory()' },
    { name: 'spaced NO_SIDE_EFFECTS annotations stay', code: '/* @__NO_SIDE_EFFECTS__ */ function factory() {}' },
    { name: 'tight NO_SIDE_EFFECTS annotations stay', code: '/*#__NO_SIDE_EFFECTS__*/ function factory() {}' },
    { name: 'jsx pragmas stay', code: '/** @jsx h */\nconst value = 1' },
    { name: 'jsxRuntime pragmas stay', code: '/** @jsxRuntime automatic */\nconst value = 1' },
    { name: 'jsxFrag pragmas stay', code: '/** @jsxFrag Fragment */\nconst value = 1' },
    { name: 'biome ignores stay', code: '// biome-ignore lint: false positive\nconst value = 1' },
    { name: 'a line Why note stays', code: '// Why: cache keys must stay stable.\nconst value = 1' },
    { name: 'a block Why note stays', code: '/* Why: cache keys must stay stable. */\nconst value = 1' },
    { name: 'a trailing Why note stays', code: 'const value = 1 // Why: trailing explanation.' },
    { name: 'allow keeps a matching block', code: '/* TODO: keep this until the rewrite */\nconst value = 1', options: { allow: ['^TODO:'] } },
    { name: 'why false keeps directives', code: '// eslint-disable-next-line foo\nconst value = 1', options: { why: false } },
    { name: 'JSX without comments passes', code: 'function View() { return <div>Hello</div> }' },
    {
      name: 'a disable-next-line target blocks the fix',
      code: '// eslint-disable-next-line foo\n// leftover thought\nconst value = 1',
      output: null,
      errors: ['comment'],
    },
    { name: 'a JSX comment container blocks the fix', code: 'function View() { return <div>{/* hide */}</div> }', output: null, errors: ['comment'] },
    { name: 'removes a line comment', code: '// load the user\nconst user = await load(id)', output: 'const user = await load(id)', errors: ['comment'] },
    {
      name: 'removes a trailing comment',
      code: 'const value = 1 // leftover\nconst other = 2',
      output: 'const value = 1\nconst other = 2',
      errors: ['comment'],
    },
    {
      name: 'keeps the blank line after a trailing comment',
      code: 'const value = 1 // leftover\n\nconst other = 2',
      output: 'const value = 1\n\nconst other = 2',
      errors: ['comment'],
    },
    { name: 'removes adjacent blocks in one report', code: 'const value = 1 /* a */ /* b */', output: 'const value = 1', errors: ['comment'] },
    { name: 'keeps one space where an inline block was', code: 'const value = 1 /* a */ + 2', output: 'const value = 1 + 2', errors: ['comment'] },
    { name: 'removes a comment run in one report', code: '// first line.\n// second line.\nconst value = 1', output: 'const value = 1', errors: ['comment'] },
    {
      name: 'one report per separate comment',
      code: '// leftover one\nconst value = 1\n// leftover two',
      output: 'const value = 1\n',
      errors: ['comment', 'comment'],
    },
    { name: 'keeps tokens apart', code: 'export/* note */const value = 1', output: 'export const value = 1', errors: ['comment'] },
    { name: 'keeps the line break of a block', code: 'function f() { return /* note\n */ 42 }', output: 'function f() { return \n 42 }', errors: ['comment'] },
    {
      name: 'keeps a unicode line separator',
      code: 'function f() { return /* note\u2028 */ 42 }',
      output: 'function f() { return \u2028 42 }',
      errors: ['comment'],
    },
    { name: 'removes jsdoc by default', code: '/** Public contract. */\nexport const value = 1', output: 'export const value = 1', errors: ['comment'] },
    { name: 'Why is case sensitive', code: '// why: lowercase is not the escape.\nconst value = 1', output: 'const value = 1', errors: ['comment'] },
    {
      name: 'why false removes Why notes',
      code: '// Why: keep this.\nconst value = 1',
      options: { why: false },
      output: 'const value = 1',
      errors: ['comment'],
    },
    {
      name: 'removes a leftover above a Why note',
      code: '// leftover thought\n// Why: keep this.\nconst value = 1',
      output: '// Why: keep this.\nconst value = 1',
      errors: ['comment'],
    },
    {
      name: 'removes a comment beside a directive',
      code: '/* oxlint-disable-next-line no-console */ /* note */\nconsole.log("x")',
      output: '/* oxlint-disable-next-line no-console */\nconsole.log("x")',
      errors: ['comment'],
    },
    {
      name: 'removes a comment inside a JSX expression',
      code: 'function View() { return <div>{/* note */ 1}</div> }',
      output: 'function View() { return <div>{ 1}</div> }',
      errors: ['comment'],
    },
    {
      name: 'keeps CRLF line endings',
      code: 'interface Props {\r\n  /** The title. */\r\n  \r\n  title: string\r\n}',
      output: 'interface Props {\r\n  title: string\r\n}',
      errors: ['comment'],
    },
    {
      name: 'members also reports both kinds',
      code: '// leftover\nconst props = {\n  // The title.\n  title: 1\n}',
      options: { members: 'also' },
      output: 'const props = {\n  title: 1\n}',
      errors: ['comment', 'memberComment'],
    },
    {
      name: 'members only removes an interface member comment',
      code: 'interface Props {\n  // Method documentation.\n  render(): void\n}',
      options: { members: 'only' },
      output: 'interface Props {\n  render(): void\n}',
      errors: ['memberComment'],
    },
    {
      name: 'members only stops at member tokens',
      code: 'interface Props { title: string; // The title.\n  count: number\n}',
      options: { members: 'only' },
      output: 'interface Props { title: string;\n  count: number\n}',
      errors: ['memberComment'],
    },
    {
      name: 'members only keeps one space around an inline comment',
      code: 'type Props = { /* The title. */ title: string }',
      options: { members: 'only' },
      output: 'type Props = { title: string }',
      errors: ['memberComment'],
    },
    {
      name: 'members only reports nested members separately',
      code: 'type Props = {\n  // Outer.\n  nested: {\n    // Inner.\n    value: string\n  }\n}',
      options: { members: 'only' },
      output: 'type Props = {\n  nested: {\n    value: string\n  }\n}',
      errors: ['memberComment', 'memberComment'],
    },
    {
      name: 'members only checks object spreads',
      code: 'const o = {\n  // Spread it.\n  ...rest,\n  k: 1,\n}',
      options: { members: 'only' },
      output: 'const o = {\n  ...rest,\n  k: 1,\n}',
      errors: ['memberComment'],
    },
    {
      name: 'members only checks parameter types',
      code: 'function render(props: {\n  /** The title. */\n  title: string\n}) {}',
      options: { members: 'only' },
      output: 'function render(props: {\n  title: string\n}) {}',
      errors: ['memberComment'],
    },
    {
      name: 'members only with why false',
      code: 'interface Props {\n  // Why: upstream rejects null.\n  title: string\n}',
      options: { members: 'only', why: false },
      output: 'interface Props {\n  title: string\n}',
      errors: ['memberComment'],
    },
    {
      name: 'members only removes an object line comment',
      code: "const props = {\n // The title.\n title: 'Hello'\n}",
      options: { members: 'only' },
      output: "const props = {\n title: 'Hello'\n}",
      errors: ['memberComment'],
    },
    {
      name: 'members only removes an object doc block',
      code: "const props = {\n /** The title. */\n title: 'Hello'\n}",
      options: { members: 'only' },
      output: "const props = {\n title: 'Hello'\n}",
      errors: ['memberComment'],
    },
    {
      name: 'members only removes an object block comment',
      code: "const props = {\n /* The title. */\n title: 'Hello'\n}",
      options: { members: 'only' },
      output: "const props = {\n title: 'Hello'\n}",
      errors: ['memberComment'],
    },
    {
      name: 'members only removes a trailing method comment',
      code: 'interface Props { render(): void; // Method comment.\n title: string }',
      options: { members: 'only' },
      output: 'interface Props { render(): void;\n title: string }',
      errors: ['memberComment'],
    },
    {
      name: 'members only removes a line comment and its blank line',
      code: 'interface Props {\n  // The title.\n\n  title: string\n}',
      options: { members: 'only' },
      output: 'interface Props {\n  title: string\n}',
      errors: ['memberComment'],
    },
    {
      name: 'members only removes a block and its blank line',
      code: 'interface Props {\n  /* The title. */\n\n  title: string\n}',
      options: { members: 'only' },
      output: 'interface Props {\n  title: string\n}',
      errors: ['memberComment'],
    },
    {
      name: 'members only with why false removes a Why block',
      code: 'interface Props {\n /* Why: upstream rejects null. */\n title: string\n}',
      options: { members: 'only', why: false },
      output: 'interface Props {\n title: string\n}',
      errors: ['memberComment'],
    },
    {
      name: 'members only with why false removes a Why doc block',
      code: 'interface Props {\n /**\n  * Why: upstream rejects null.\n  */\n title: string\n}',
      options: { members: 'only', why: false },
      output: 'interface Props {\n title: string\n}',
      errors: ['memberComment'],
    },
    {
      name: 'members only removes a comment run',
      code: 'interface Props {\n // First line.\n // Second line.\n title: string\n}',
      options: { members: 'only' },
      output: 'interface Props {\n title: string\n}',
      errors: ['memberComment'],
    },
    {
      name: 'members only treats lowercase why as a comment',
      code: 'interface Props {\n // why: lowercase is not the escape.\n title: string\n}',
      options: { members: 'only' },
      output: 'interface Props {\n title: string\n}',
      errors: ['memberComment'],
    },
    {
      name: 'members only removes a bang line comment',
      code: 'interface Props {\n // ! important\n title: string\n}',
      options: { members: 'only' },
      output: 'interface Props {\n title: string\n}',
      errors: ['memberComment'],
    },
    {
      name: 'members only removes a spaced bang block',
      code: 'interface Props {\n /* ! not a legal block */\n title: string\n}',
      options: { members: 'only' },
      output: 'interface Props {\n title: string\n}',
      errors: ['memberComment'],
    },
    {
      name: 'members only removes a JSX component prop comment',
      filename: '/repo/component.tsx',
      code: 'function View(props: {\n // The title.\n title: string\n}) { return <h1>{props.title}</h1> }',
      options: { members: 'only' },
      output: 'function View(props: {\n title: string\n}) { return <h1>{props.title}</h1> }',
      errors: ['memberComment'],
    },
    { name: 'removes a leading line comment', code: '// leftover thought\nconst value = 1', output: 'const value = 1', errors: ['comment'] },
    { name: 'removes a trailing line comment at the end', code: 'const value = 1 // leftover thought', output: 'const value = 1', errors: ['comment'] },
    { name: 'removes a trailing line comment before code', code: 'const value = 1 // leftover thought\nconst other = 2', output: 'const value = 1\nconst other = 2', errors: ['comment'] },
    { name: 'removes a trailing block comment', code: 'const value = 1 /* leftover */', output: 'const value = 1', errors: ['comment'] },
    { name: 'keeps operators apart', code: 'const value = a +/* note */+ b', output: 'const value = a + + b', errors: ['comment'] },
    { name: 'keeps a keyword apart from its value', code: 'function f() { return/* note */value }', output: 'function f() { return value }', errors: ['comment'] },
    { name: 'keeps a number apart from its member', code: 'const value = 1/* note */.toString()', output: 'const value = 1 .toString()', errors: ['comment'] },
    {
      name: 'removes a comment run between statements',
      code: 'const value = 1\n// first line.\n// second line.\nconst other = 2',
      output: 'const value = 1\nconst other = 2',
      errors: ['comment'],
    },
    { name: 'removes a plain block above an export', code: '/* Public contract. */\nexport const value = 1', output: 'export const value = 1', errors: ['comment'] },
    { name: 'removes a trailing comment below a Why note', code: '// Why: keep this.\nconst value = 1 // unrelated', output: '// Why: keep this.\nconst value = 1', errors: ['comment'] },
    { name: 'a block disable-next-line target blocks the fix', code: '/* oxlint-disable-next-line foo */\n// leftover thought\nconst value = 1', output: null, errors: ['comment'] },
    { name: 'a directive beside a note blocks the fix', code: '/* oxlint-disable-next-line no-console */ /* note */\n// note\nconsole.log("x")', output: null, errors: ['comment'] },
    { name: 'removes a comment inside a function', code: 'function render() {\n // Local explanation.\n return 1\n}', output: 'function render() {\n return 1\n}', errors: ['comment'] },
    { name: 'removes a trailing comment after a semicolon', code: 'const value = 1; // leftover.\nconst other = 2', output: 'const value = 1;\nconst other = 2', errors: ['comment'] },
    { name: 'removes a bang line comment', code: '// ! important\nconst value = 1', output: 'const value = 1', errors: ['comment'] },
    { name: 'removes a spaced bang block', code: '/* ! not a legal block */\nconst value = 1', output: 'const value = 1', errors: ['comment'] },
    { name: 'a fragment comment container blocks the fix', filename: '/repo/component.tsx', code: 'function View() { return <>{/* hide */}</> }', output: null, errors: ['comment'] },
    {
      name: 'a multi-line JSX comment container blocks the fix',
      filename: '/repo/component.tsx',
      code: 'function View() {\n return (\n <div>\n {/* hide */}\n <span />\n </div>\n )\n}',
      output: null,
      errors: ['comment'],
    },
    { name: 'a JSX comment between text lines blocks the fix', filename: '/repo/component.tsx', code: 'const view = <p>Hello\n{/* note */}\nworld</p>', output: null, errors: ['comment'] },
    { name: 'a JSX comment inside text blocks the fix', filename: '/repo/component.tsx', code: 'function View() { return <p>Hello {/* note */}world</p> }', output: null, errors: ['comment'] },
  ])('$name', (row) => testerRun(commentsCode, row))
})
